import sys

def solve() -> None:
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    # Remove possible empty lines
    data = [line.strip() for line in data if line.strip() != ""]
    if not data:
        return
    idx = 0
    try:
        counter = int(data[idx])
    except:
        counter = 0
    idx += 1
    if idx >= len(data):
        # No operations count, just print final value
        print(f"Final Counter Value: {counter}")
        return
    try:
        ops_cnt = int(data[idx])
    except:
        ops_cnt = 0
    idx += 1

    for i in range(ops_cnt):
        if idx >= len(data):
            break
        op = data[idx].lower()
        idx += 1
        if op == 'inc':
            counter += 1
            print(f"Incremented: {counter}")
        elif op == 'dec':
            counter -= 1
            print(f"Decremented: {counter}")
        else:
            # ignore unknown operation
            continue

    print(f"Final Counter Value: {counter}")

if __name__ == "__main__":
    solve()
